// src/hook/useCRUD.jsx
import { useState } from "react";
import axios_api from "../api/axios";
import { apiPath } from "../api/config";

export const useCRUD = ({ initFormData, api, keyField = "id" }) => {
  const [items, setItems] = useState([]);
  const [formData, setFormData] = useState(initFormData());
  const [selectedItem, setSelectedItem] = useState(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isEditOpen, setIsEditOpen] = useState(false);

  // FK 보조 상태
  const [customer, setCustomer] = useState([]);
  const [itemList, setItemList] = useState([]);
  const [customerId, setCustomerId] = useState(null);
  const [itemListId, setItemListId] = useState(null);
  const [orderQty, setOrderQty] = useState(1);

  const crudKey = keyField;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleCreate = async () => {
    try {
      const created = await api.create(formData);
      if (api && typeof api.getAll === "function") {
        const list = await api.getAll();
        setItems(list);
      } else {
        setItems(prev => [...prev, created]);
      }
      setIsCreateOpen(false);
      setFormData(initFormData());
      return true;
    } catch (err) {
      const msg =
        err?.response?.data?.error ||
        err?.response?.data?.message ||
        err?.message || "등록 중 에러";
      alert(msg);
      console.error(err);
      return false;
    }
  };

  const handleUpdate = async () => {
    try {
      const payload = { ...selectedItem, ...formData };
      const idKey = crudKey;
      if (!payload?.[idKey]) {
        alert("ID가 없습니다. 행을 클릭해 다시 시도하세요.");
        return false;
      }
      await api.update(payload);
      setItems(prev => prev.map(item =>
        item[idKey] === payload[idKey] ? { ...item, ...payload } : item
      ));
      setIsEditOpen(false);
      return true;
    } catch (err) {
      const msg = err?.response?.data?.error || err?.message || "수정 중 에러";
      alert(`수정 실패 : ${msg}`);
      console.error(err);
      return false;
    }
  };

  const handleDelete = async () => {
    if (!selectedItem) return;
    try {
      await api.delete(selectedItem[crudKey]);
      alert("삭제 완료.");
      setIsEditOpen(false);
      setItems(prev => prev.filter(item => item[crudKey] !== selectedItem[crudKey]));
    } catch (err) {
      const msg =
        err?.response?.data?.error ||
        err?.response?.data?.message ||
        err?.message || "삭제 중 에러";
      alert(`삭제 실패 : ${msg}`);
      console.error(err);
    }
  };

  const openEdit = (item) => {
    setFormData(prev => ({ ...initFormData(), ...item }));
    setSelectedItem(item);
    setIsEditOpen(true);
  };
  const openCreate = () => {
    setFormData(initFormData());
    setIsCreateOpen(true);
    setSelectedItem(null);
  };
  const closeCreate = () => setIsCreateOpen(false);
  const closeEdit = () => setIsEditOpen(false);

  // 주문 등록 샘플: 반드시 apiPath + axios_api 사용
  const onSubmit = async (e) => {
    e.preventDefault();
    if (!customerId || !itemListId || !orderQty) {
      alert("거래처, 상품, 수량을 모두 선택/입력해주세요.");
      return;
    }
    const url = apiPath("/order/orderlist");
    try {
      await axios_api.post(url, {
        customerId,
        itemId: itemListId,
        orderQty,
        orderPrice: formData.orderPrice,
        orderState: formData.orderState || "판매대기",
        orderDeliState: formData.orderDeliState || "납품대기",
        orderDate: formData.orderDate,
        deliveryDate: formData.deliveryDate,
        cusAddr: formData.cusAddr,
      });
      alert("주문 완료");
    } catch (err) {
      console.error("주문 실패:", err);
      alert(err?.response?.data?.message || "주문 중 오류가 발생했습니다.");
    }
  };

  return {
    items,
    setItems,
    formData,
    setFormData,
    selectedItem,
    handleChange,
    handleCreate,
    handleUpdate,
    handleDelete,
    openCreate,
    openEdit,
    closeCreate,
    closeEdit,
    isCreateOpen,
    isEditOpen,

    // FK 상태
    customer, setCustomer,
    itemList, setItemList,
    customerId, setCustomerId,
    itemListId, setItemListId,
    setOrderQty,

    onSubmit,
  };
};
